import java.util.*;

class Solution {
  public int maxPathLength(int[][] coordinates, int k) {
    int n = coordinates.length;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    Arrays.sort(
        order,
        (a, b) ->
            coordinates[a][0] != coordinates[b][0]
                ? Integer.compare(coordinates[a][0], coordinates[b][0])
                : Integer.compare(coordinates[b][1], coordinates[a][1]));
    int target = 0;
    for (int i = 0; i < n; i++) if (order[i] == k) target = i;
    int[] ys = new int[n];
    for (int i = 0; i < n; i++) ys[i] = coordinates[i][1];
    Arrays.sort(ys);
    int[] left = new int[n], right = new int[n];
    int[] bit = new int[n + 1];
    for (int i = 0; i < n; i++) {
      int rank = lowerBound(ys, coordinates[order[i]][1]) + 1;
      left[i] = 1 + query(bit, rank - 1);
      update(bit, rank, left[i]);
    }
    Arrays.fill(bit, 0);
    for (int end = n - 1; end >= 0; ) {
      int begin = end;
      int x = coordinates[order[end]][0];
      while (begin >= 0 && coordinates[order[begin]][0] == x) begin--;
      for (int i = end; i > begin; i--) {
        int rank = n - lowerBound(ys, coordinates[order[i]][1]);
        right[i] = 1 + query(bit, rank - 1);
      }
      for (int i = end; i > begin; i--) {
        int rank = n - lowerBound(ys, coordinates[order[i]][1]);
        update(bit, rank, right[i]);
      }
      end = begin;
    }
    return left[target] + right[target] - 1;
  }

  private int lowerBound(int[] a, int value) {
    int lo = 0, hi = a.length;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (a[mid] < value) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  private int query(int[] bit, int index) {
    int result = 0;
    while (index > 0) {
      result = Math.max(result, bit[index]);
      index -= index & -index;
    }
    return result;
  }

  private void update(int[] bit, int index, int value) {
    while (index < bit.length) {
      bit[index] = Math.max(bit[index], value);
      index += index & -index;
    }
  }
}
